// Package store owns the SQLite file and every write the service performs.
package store

import (
	"context"
	"database/sql"
	"errors"
	"fmt"
	"sync"
	"time"

	_ "modernc.org/sqlite"
)

// ErrNotFound reports that no record exists for the requested resource.
var ErrNotFound = errors.New("resource not found")

// Status values returned by the lock operations.
const (
	StatusAcquired         = "ACQUIRED"
	StatusReentered        = "REENTERED"
	StatusWaiting          = "WAITING"
	StatusReleased         = "RELEASED"
	StatusReentryDecrement = "REENTRY_DECREMENTED"
	StatusDuplicateWaiting = "DUPLICATE_WAITING"
	StatusLeaseExpired     = "LEASE_EXPIRED"
	StatusNotOwner         = "NOT_OWNER"
)

// WaitingOwner is one queued request, in queue order.
type WaitingOwner struct {
	OwnerID                string `json:"ownerId"`
	RequestedLeaseSeconds  int    `json:"requestedLeaseSeconds"`
}

// State is the full, queryable picture of one resource.
type State struct {
	ResourceID      string
	OwnerID         string
	LeaseExpiresAt  *time.Time
	ReentryCount    int
	WaitingOwners   []WaitingOwner
}

// AcquireResult describes the outcome of one acquire call.
type AcquireResult struct {
	Status string
	State  State
}

// ReleaseResult describes the outcome of one release call.
type ReleaseResult struct {
	Status string
	State  State
}

// ReenterResult describes the outcome of one reentry call.
type ReenterResult struct {
	Status string
	State  State
}

// Store wraps the SQLite handle so callers never touch database/sql directly.
type Store struct {
	db      *sql.DB
	mu      sync.Mutex
	nowFunc func() time.Time

	stopReaper context.CancelFunc
	reaperDone chan struct{}
}

// Open prepares the database file and the schema this service needs.
func Open(path string) (*Store, error) {
	db, err := sql.Open("sqlite", path)
	if err != nil {
		return nil, fmt.Errorf("open sqlite: %w", err)
	}
	// One connection plus the in-process mutex is what keeps every state transition
	// atomic: two requests can never read the same holder state and race a transfer.
	db.SetMaxOpenConns(1)
	if _, err := db.Exec("PRAGMA journal_mode=WAL"); err != nil {
		db.Close()
		return nil, fmt.Errorf("enable wal: %w", err)
	}
	if _, err := db.Exec("PRAGMA busy_timeout=5000"); err != nil {
		db.Close()
		return nil, fmt.Errorf("set busy timeout: %w", err)
	}
	if _, err := db.Exec(schema); err != nil {
		db.Close()
		return nil, fmt.Errorf("apply schema: %w", err)
	}

	s := &Store{db: db, nowFunc: time.Now}
	ctx, cancel := context.WithCancel(context.Background())
	s.stopReaper = cancel
	s.reaperDone = make(chan struct{})
	go s.runReaper(ctx)
	return s, nil
}

// Ping reports whether the storage layer is usable.
func (s *Store) Ping() error { return s.db.Ping() }

// Close stops the expiry worker and releases the database handle.
func (s *Store) Close() error {
	if s.stopReaper != nil {
		s.stopReaper()
		<-s.reaperDone
	}
	return s.db.Close()
}

// GetState returns the current, unmodified picture of a resource. The read never
// extends a lease, never changes the queue and never promotes a waiting owner.
func (s *Store) GetState(resourceID string) (State, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	tx, err := s.db.Begin()
	if err != nil {
		return State{}, err
	}
	defer tx.Rollback()
	state, err := s.loadState(tx, resourceID)
	if err != nil {
		return State{}, err
	}
	return state, nil
}

// Acquire implements the lock entry: first caller owns, the same owner only bumps
// reentryCount, and everyone else queues once in arrival order.
func (s *Store) Acquire(resourceID, ownerID string, leaseSeconds int) (AcquireResult, error) {
	s.mu.Lock()
	defer s.mu.Unlock()

	tx, err := s.db.Begin()
	if err != nil {
		return AcquireResult{}, err
	}
	defer tx.Rollback()
	now := s.nowFunc()

	row := tx.QueryRow(`SELECT owner_id, lease_expires_at, reentry_count, expired_owner_id FROM resources WHERE resource_id = ?`, resourceID)
	var currentOwner sql.NullString
	var expiresAt sql.NullInt64
	var reentryCount int
	var expiredOwner sql.NullString
	switch err := row.Scan(&currentOwner, &expiresAt, &reentryCount, &expiredOwner); {
	case errors.Is(err, sql.ErrNoRows):
		if _, err := tx.Exec(
			`INSERT INTO resources(resource_id, owner_id, lease_expires_at, reentry_count) VALUES(?, ?, ?, 1)`,
			resourceID, ownerID, now.Add(time.Duration(leaseSeconds)*time.Second).UnixMilli(),
		); err != nil {
			return AcquireResult{}, err
		}
		if err := tx.Commit(); err != nil {
			return AcquireResult{}, err
		}
		state, err := s.readCommitted(resourceID)
		if err != nil {
			return AcquireResult{}, err
		}
		return AcquireResult{Status: StatusAcquired, State: state}, nil
	case err != nil:
		return AcquireResult{}, err
	}

	// An expired lease moves on deterministically before this request is handled, so
	// a late request from the previous owner can never overwrite the new holder.
	if currentOwner.Valid && expiresAt.Valid && now.UnixMilli() >= expiresAt.Int64 {
		if err := s.promoteExpired(tx, resourceID, now); err != nil {
			return AcquireResult{}, err
		}
		row = tx.QueryRow(`SELECT owner_id, lease_expires_at, reentry_count, expired_owner_id FROM resources WHERE resource_id = ?`, resourceID)
		if err := row.Scan(&currentOwner, &expiresAt, &reentryCount, &expiredOwner); err != nil {
			return AcquireResult{}, err
		}
	}

	switch {
	case !currentOwner.Valid:
		// Holderless resource (the previous lease expired with an empty queue): first caller owns.
		expiry := now.Add(time.Duration(leaseSeconds) * time.Second).UnixMilli()
		if _, err := tx.Exec(
			`UPDATE resources SET owner_id = ?, lease_expires_at = ?, reentry_count = 1, expired_owner_id = NULL WHERE resource_id = ?`,
			ownerID, expiry, resourceID,
		); err != nil {
			return AcquireResult{}, err
		}
		if err := tx.Commit(); err != nil {
			return AcquireResult{}, err
		}
		state, err := s.readCommitted(resourceID)
		if err != nil {
			return AcquireResult{}, err
		}
		return AcquireResult{Status: StatusAcquired, State: state}, nil
	case currentOwner.String == ownerID:
		// Reentry of the live owner: a single ownership record, same lease window.
		if _, err := tx.Exec(
			`UPDATE resources SET reentry_count = reentry_count + 1, expired_owner_id = NULL WHERE resource_id = ?`,
			resourceID,
		); err != nil {
			return AcquireResult{}, err
		}
		if err := tx.Commit(); err != nil {
			return AcquireResult{}, err
		}
		state, err := s.readCommitted(resourceID)
		if err != nil {
			return AcquireResult{}, err
		}
		return AcquireResult{Status: StatusReentered, State: state}, nil
	}

	// Another owner holds the live lease: queue once.
	var queued string
	waitErr := tx.QueryRow(
		`SELECT owner_id FROM waiting_requests WHERE resource_id = ? AND owner_id = ?`,
		resourceID, ownerID,
	).Scan(&queued)
	switch {
	case waitErr == nil:
		state, err := s.loadState(tx, resourceID)
		if err != nil {
			return AcquireResult{}, err
		}
		return AcquireResult{Status: StatusDuplicateWaiting, State: state}, nil
	case !errors.Is(waitErr, sql.ErrNoRows):
		return AcquireResult{}, waitErr
	}
	if _, err := tx.Exec(
		`INSERT INTO waiting_requests(resource_id, owner_id, requested_lease_seconds) VALUES(?, ?, ?)`,
		resourceID, ownerID, leaseSeconds,
	); err != nil {
		return AcquireResult{}, err
	}
