// GetState returns the read-only public view of one resource.
func (s *Store) GetState(resourceID string) (State, error) {
	s.mu.Lock()
	defer s.mu.Unlock()
	return readState(s.db, resourceID)
}

// ReapExpired deterministically transfers every resource whose lease is due. It is
// driven by the background reaper and can also be invoked directly from tests.
func (s *Store) ReapExpired() error {
	s.mu.Lock()
	defer s.mu.Unlock()

	tx, err := s.db.Begin()
	if err != nil {
		return err
	}
	defer tx.Rollback()

	now := s.now()
	rows, err := tx.Query(
		`SELECT resource_id FROM resources
		 WHERE owner_id IS NOT NULL AND lease_expires_at IS NOT NULL AND lease_expires_at <= ?`,
		now.UnixMilli(),
	)
	if err != nil {
		return err
	}
	var ids []string
	for rows.Next() {
		var id string
		if err := rows.Scan(&id); err != nil {
			rows.Close()
			return err
		}
		ids = append(ids, id)
	}
	rows.Close()
	if err := rows.Err(); err != nil {
		return err
	}

	for _, id := range ids {
		row, err := readRow(tx, id)
		if err != nil {
			return err
		}
		if err := promoteExpired(tx, id, row, now); err != nil {
			return err
		}
	}
	return tx.Commit()
}

func readRow(tx *sql.Tx, resourceID string) (resourceRow, error) {
	var row resourceRow
	err := tx.QueryRow(
		`SELECT owner_id, lease_expires_at, reentry_count, expired_owner_id
		 FROM resources WHERE resource_id = ?`,
		resourceID,
	).Scan(&row.ownerID, &row.leaseExpiresAt, &row.reentryCount, &row.expiredOwnerID)
	return row, err
}

func isWaiting(tx *sql.Tx, resourceID, ownerID string) (bool, error) {
	var count int
	if err := tx.QueryRow(
		`SELECT COUNT(*) FROM waiting_requests WHERE resource_id = ? AND owner_id = ?`,
		resourceID, ownerID,
	).Scan(&count); err != nil {
		return false, err
	}
	return count > 0, nil
}

func leaseDuration(seconds int64) time.Duration {
	return time.Duration(seconds) * time.Second
}

// promoteExpired moves an expired lock to the head waiter (using that waiter's
// requested lease seconds) or leaves the resource without a holder. The former owner
// is remembered so its late release/reentry still reports LEASE_EXPIRED.
func promoteExpired(tx *sql.Tx, resourceID string, row resourceRow, now time.Time) error {
	return transfer(tx, resourceID, row.ownerID.String, now, true)
}

// promoteAfterRelease moves a voluntarily released lock to the head waiter without
// blaming the releasing owner for an expiration.
func promoteAfterRelease(tx *sql.Tx, resourceID string, now time.Time) error {
	return transfer(tx, resourceID, "", now, false)
}

func transfer(tx *sql.Tx, resourceID, formerOwner string, now time.Time, expired bool) error {
	var nextOwner string
	var leaseSeconds int64
