			`UPDATE resources
			 SET owner_id = NULL, lease_expires_at = NULL, reentry_count = 0, expired_owner_id = ?
			 WHERE resource_id = ?`,
			expiredOwner, resourceID,
		)
		return err
	}
	if err != nil {
		return err
	}
	if _, err := tx.Exec(
		`DELETE FROM waiting_requests WHERE resource_id = ? AND owner_id = ?`,
		resourceID, nextOwner,
	); err != nil {
		return err
	}
	expiredOwner := sql.NullString{}
	if expired {
		expiredOwner = sql.NullString{String: formerOwner, Valid: true}
	}
