func TestLeaseExpiresAndTransfersEndToEnd(t *testing.T) {
	router := newRouter(t)

	doJSON(t, router, http.MethodPost, "/locks", map[string]any{
		"resourceId": "r", "ownerId": "a", "leaseSeconds": 1,
	})
	doJSON(t, router, http.MethodPost, "/locks", map[string]any{
		"resourceId": "r", "ownerId": "b", "leaseSeconds": 90,
	})

